constexpr double GAMMA_SD=2.212761569e5,MIN_SD=1e-15,MAX_SD=1e-9;
V xprod(V a,V b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}
struct BB {double mm=0,mg=0,gg=0;};
struct SD {Spins m,prev,Gprev;int updates=0,resets=0,stable=0;double aux=0,dt=MIN_SD;};
Spins gradient_sd(const Spins&m,const Spins&H){Spins g=m;for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++)g[i][j]=xprod(m[i][j],xprod(m[i][j],H[i][j]))*(GAMMA_SD/2);return g;}
BB bb_sd(const Spins&m,const Spins&g,const Spins&p,const Spins&pg){BB b;for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++){auto dm=(m[i][j]-p[i][j])*1e-6,dg=(g[i][j]-pg[i][j])*1e-6;b.mm+=dot(dm,dm);b.mg+=dot(dm,dg);b.gg+=dot(dg,dg);}return b;}
double choose_sd(BB b,int iteration,int&resets){if(!std::isfinite(b.mm)||!std::isfinite(b.mg)||!std::isfinite(b.gg))throw std::runtime_error("nonfinite BB");double dt=MIN_SD;bool bad=false;if(iteration%2){if(b.mg&&b.mm*b.mg>0)dt=b.mm/b.mg;else if(b.gg&&b.mg*b.gg>0)dt=b.mg/b.gg;else bad=true;}else{if(b.gg&&b.mg*b.gg>0)dt=b.mg/b.gg;else if(b.mg&&b.mm*b.mg>0)dt=b.mm/b.mg;else bad=true;}dt=std::min(MAX_SD,std::max(MIN_SD,dt));if(bad)dt=std::min(MAX_SD,(++resets)*MIN_SD);else resets=0;return dt;}
inline double SD_RAW_MAX_LAST=0;
V rational_sd(V m,V H,double dt,double Ms){auto q=xprod(m,H*(dt*GAMMA_SD/4));auto r=(m*(1-dot(q,q))-xprod(m,q)*2)*(1/(1+dot(q,q)));SD_RAW_MAX_LAST=std::max(SD_RAW_MAX_LAST,std::abs(norm(r)-1));auto M=r*Ms;double n=norm(M);if(!finite(M)||n==0)throw std::runtime_error("nonfinite/zero update");M=M*(Ms/n);return M*(1/Ms);}
BB advance_sd(SD&s,const Spins&H){SD_RAW_MAX_LAST=0;auto g=gradient_sd(s.m,H);BB b;if(s.updates)b=bb_sd(s.m,g,s.prev,s.Gprev);s.dt=s.updates?choose_sd(b,s.updates,s.resets):MIN_SD;s.prev=s.m;s.Gprev=std::move(g);for(int i=0;i<2;i++)for(size_t j=0;j<s.m[i].size();j++)s.m[i][j]=rational_sd(s.m[i][j],H[i][j],s.dt,i==0?3e5:6e5);s.updates++;s.aux+=s.dt;return b;}
void sd_checkpoint(const std::filesystem::path&p,const SD&s){auto tmp=p;tmp+=".tmp";std::ofstream f(tmp,std::ios::binary);char magic[16]="SD-v380-v1";f.write(magic,16);int controls[3]={s.updates,s.resets,s.stable};double vals[2]={s.aux,s.dt};f.write((const char*)controls,sizeof(controls));f.write((const char*)vals,sizeof(vals));for(auto*a:{&s.m,&s.prev,&s.Gprev})for(auto&v:*a)for(auto q:v){double x[3]={q.x,q.y,q.z};f.write((const char*)x,sizeof(x));}f.close();if(!f)throw std::runtime_error("SD checkpoint write");std::filesystem::rename(tmp,p);}
SD sd_restore(const std::filesystem::path&p){SD s;std::ifstream f(p,std::ios::binary);char magic[16],expected[16]="SD-v380-v1";f.read(magic,16);if(!std::equal(magic,magic+16,expected))throw std::runtime_error("SD checkpoint schema");int c[3];double v[2];f.read((char*)c,sizeof(c));f.read((char*)v,sizeof(v));s.updates=c[0];s.resets=c[1];s.stable=c[2];s.aux=v[0];s.dt=v[1];for(auto*a:{&s.m,&s.prev,&s.Gprev})for(auto&w:*a){w.resize(15625);for(auto&q:w){double x[3];f.read((char*)x,sizeof(x));q={x[0],x[1],x[2]};if(!finite(q))throw std::runtime_error("SD checkpoint finite");}}if(!f||f.peek()!=EOF||s.updates<1||s.updates>10000)throw std::runtime_error("SD checkpoint size/control");return s;}
